From 1bb55c70010042da21e489bccc3d94216a6799b3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:04:05 +0100
Subject: [PATCH] applets/systemtray: keep the highlight on its icon when items
 change

When a tray icon appeared or went away, the highlight of the open applet
jumped off its icon for a few frames, since it was only moved afterwards
and even animated into the re-created delegate. Now it follows at once.

BUG: 517561
---
 .../systemtray/qml/CurrentItemHighLight.qml   | 26 ++++++++++++++++++-
 1 file changed, 25 insertions(+), 1 deletion(-)

diff --git a/applets/systemtray/qml/CurrentItemHighLight.qml b/applets/systemtray/qml/CurrentItemHighLight.qml
index c1bf279a3a..72c012cf9f 100644
--- a/applets/systemtray/qml/CurrentItemHighLight.qml
+++ b/applets/systemtray/qml/CurrentItemHighLight.qml
@@ -17,6 +17,7 @@ KSvg.FrameSvgItem {

     property bool animationEnabled: true
     property var highlightedItem: null
+    property var highlightedApplet: null

     property var containerMargins: {
         let item = currentItemHighLight;
@@ -75,6 +76,16 @@ KSvg.FrameSvgItem {
         }
     }

+    // update as soon as the applet's new container is ready (e.g. after tray items were re-sorted)
+    Connections {
+        target: systemTrayState.activeApplet ? systemTrayState.activeApplet.parent : null
+        ignoreUnknownSignals: true
+
+        function onInVisibleLayoutChanged() {
+            currentItemHighLight.updateHighlightedItem();
+        }
+    }
+
     // update when System Tray size changes
     Connections {
         target: parent
@@ -95,6 +106,15 @@ KSvg.FrameSvgItem {
         function onScaleChanged() {
             Qt.callLater(currentItemHighLight.updateHighlightedItem);
         }
+
+        // follow the item right away when other tray items are added or removed
+        function onXChanged() {
+            currentItemHighLight.updateHighlightedItem();
+        }
+
+        function onYChanged() {
+            currentItemHighLight.updateHighlightedItem();
+        }
     }

     function updateHighlightedItem() {
@@ -111,9 +131,12 @@ KSvg.FrameSvgItem {
     }

     function changeHighlightedItem(nextItem, forceEdgeHighlight) {
+        const nextApplet = forceEdgeHighlight ? null : systemTrayState.activeApplet;
+
         // do not animate the first appearance
         // or when the property value of a highlighted item changes
-        if (!highlightedItem || (highlightedItem === nextItem)) {
+        // or when the highlighted applet was only moved to a new delegate
+        if (!highlightedItem || (highlightedItem === nextItem) || (nextApplet && nextApplet === highlightedApplet)) {
             animationEnabled = false;
         }

@@ -131,6 +154,7 @@ KSvg.FrameSvgItem {
         }

         highlightedItem = nextItem;
+        highlightedApplet = nextApplet;
         animationEnabled = true;
     }

-- 
